const (
	gopherMovePixel int16   = 8
	deadZone        float64 = 0.05
	maxAngle        float64 = 1.0
)

const (
	modeTitle    = 0
	modePlaying  = 1
	modeGameOver = 2
)

var (
	gameMode  int
	gopherPos int16 = 140
)

func drawBitmapFromRaw(raw string, srcW, srcH, x, y int16) {
	buf := make([]uint16, int(srcW)*int(srcH))
	for i := range buf {
		buf[i] = uint16(raw[i*2]) | uint16(raw[i*2+1])<<8
	}
	disp.DrawRGBBitmap(x, y, buf, srcW, srcH)
}

// NOTE: 左右の傾きで移動速度が違うので良い感じになるように補正している
func handleGopherMove() {
	ay := accelY()
	if ay > deadZone {
		px := int16(ay / maxAngle * float64(gopherMovePixel) * 1.7)
		gopherPos -= px
		if gopherPos < 10 {
			gopherPos = 10
		}
	} else if ay < -deadZone {
		px := int16(-ay / maxAngle * float64(gopherMovePixel) * 0.7)
		gopherPos += px
		if gopherPos > 280 {
			gopherPos = 280
		}
	}
}

func handleTitle() {
	handleGopherMove()

	if pressEnter() {
		gopherPos = 140
		calibrateAccel()
		gameMode = modePlaying
		waitRelease(pressEnter)
		return
	}

	disp.FillScreen(white)
	tinyfont.WriteLine(disp, &freesans.Regular18pt7b, 15, 140, "Push stick to start!!", black)
	drawBitmapFromRaw(gopherRaw, gopherW, gopherH, gopherPos, 65)
}

func handlePlaying() {
	handleGopherMove()

	disp.FillScreen(white)
	drawBitmapFromRaw(gopherRaw, gopherW, gopherH, gopherPos, 65)
}

func handleGameOver() {
	if pressEnter() {
		gopherPos = 140
		gameMode = modeTitle
		waitRelease(pressEnter)
		return
	}

	disp.FillScreen(white)
	tinyfont.WriteLine(disp, &freesans.Regular18pt7b, 65, 140, "Game Over!!", black)
	tinyfont.WriteLine(disp, &freesans.Regular9pt7b, 10, 210, "Push stick to go back", black)
	drawBitmapFromRaw(gopherRaw, gopherW, gopherH, 140, 65)
}

func main() {
	tick := time.Tick(16 * time.Millisecond)
	initDisplay()
	calibrateAccel()

	for {
		<-tick
		switch gameMode {
		case modeTitle:
			handleTitle()
		case modePlaying:
			handlePlaying()
		case modeGameOver:
			handleGameOver()
		}
	}
}
